import{_ as a,o as r,c as e,a3 as d}from"./chunks/framework.Dj4Lt7vj.js";const f=JSON.parse('{"title":"客户端总览","description":"","frontmatter":{"title":"客户端总览"},"headers":[],"relativePath":"client/overview.md","filePath":"client/overview.md","lastUpdated":1787949005000}'),o={name:"client/overview.md"};function i(s,t,l,n,c,h){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="客户端总览" tabindex="-1">客户端总览 <a class="header-anchor" href="#客户端总览" aria-label="Permalink to &quot;客户端总览&quot;">​</a></h1><p>登录桌面客户端后，左侧是主菜单。这一页帮你建立一张地图，知道每个入口是干什么的。</p><h2 id="左侧菜单" tabindex="-1">左侧菜单 <a class="header-anchor" href="#左侧菜单" aria-label="Permalink to &quot;左侧菜单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th><th>详细文档</th></tr></thead><tbody><tr><td>店铺客服</td><td>接入店铺、管理客服账号、开关每个账号的 AI 接待</td><td><a href="/aicare-docs/client/shops">接入店铺和客服账号</a></td></tr><tr><td>店铺方案</td><td>创建和编辑 AI 方案，决定 AI 怎么回复</td><td><a href="/aicare-docs/solution/editor">方案编辑器</a></td></tr><tr><td>AI 助手</td><td>运营助手：用对话方式了解店铺配置、获取调整建议</td><td>见下文</td></tr><tr><td>工作台</td><td>汇总当前接待中的会话和待办</td><td>—</td></tr><tr><td>扩展市场</td><td>管理知识库（我的库 / 公共库），了解高级能力</td><td><a href="/aicare-docs/knowledge/basics">知识库是什么</a></td></tr><tr><td>表格</td><td>创建查询表和登记表，供 AI 查数据、记需求</td><td><a href="/aicare-docs/solution/tables">查询表与登记表</a></td></tr><tr><td>聊天记录</td><td>按顾客查看会话记录，筛选待跟进会话</td><td><a href="/aicare-docs/workspace/records">聊天记录与数据</a></td></tr><tr><td>数据统计</td><td>接待量等统计数据</td><td>—</td></tr><tr><td>账单</td><td>点数余额、套餐、消耗记录、兑换码</td><td><a href="/aicare-docs/billing/points">点数怎么计算</a></td></tr></tbody></table><p>菜单下方还有「设置」入口和「联系我们」「新手教程」等辅助入口。</p><h2 id="设置页" tabindex="-1">设置页 <a class="header-anchor" href="#设置页" aria-label="Permalink to &quot;设置页&quot;">​</a></h2><p>设置页按分区组织：</p><ul><li><strong>缓存 / 启动</strong>：清理缓存、开机自启动等。</li><li><strong>通知</strong>：客户端提醒、微信绑定和通知记录，见<a href="/aicare-docs/client/notify">通知设置</a>。</li><li><strong>错误上报</strong>：控制报错时保存和上报的内容范围，见<a href="/aicare-docs/client/report">错误报告</a>。</li><li><strong>工作</strong>：接待运行方式，包括「同时处理多个客户」（默认关闭，每次只处理 1 个客户）和「启用宽松转接」（默认开启，见<a href="/aicare-docs/solution/transfer#宽松转接">转人工设置</a>）。</li><li><strong>新客服默认打开方式</strong>：添加新客服时窗口如何呈现。</li><li><strong>高级</strong>：调试工具，日常使用不需要。</li></ul><h2 id="ai-助手-运营助手" tabindex="-1">AI 助手（运营助手） <a class="header-anchor" href="#ai-助手-运营助手" aria-label="Permalink to &quot;AI 助手（运营助手）&quot;">​</a></h2><p>「AI 助手」是一个对话式的运营助手。你可以直接问它店铺的配置情况、让它检查知识库、或请它提出调整建议。</p><p>它给出的<strong>修改建议需要你确认后才会生效</strong>，已应用的修改支持撤销。放心提问，不会因为聊了几句就改动配置。</p><h2 id="接待时的窗口" tabindex="-1">接待时的窗口 <a class="header-anchor" href="#接待时的窗口" aria-label="Permalink to &quot;接待时的窗口&quot;">​</a></h2><p>在「店铺客服」里打开某个客服账号后，客户端会打开对应平台的客服窗口。AI 在这个窗口里读消息、发回复。接待期间保持客户端和平台窗口运行即可，可以最小化。</p>',13)])])}const _=a(o,[["render",i]]);export{f as __pageData,_ as default};
